/bin/bash -lc "node <<'JS'
const {chromium}=require('playwright');(async()=>{const b=await chromium.launch({headless:true,executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH}),p=await b.newPage({viewport:{width:320,height:900},reducedMotion:'reduce'});await p.goto('http://127.0.0.1:18770/leetcode/843/');await p.locator('#next').click();for(const l of ['en','zh']){await p.locator('[data-lang='+l+']').click();await p.locator('.table-wrap').evaluate(e=>{e.scrollLeft=e.scrollWidth;scrollTo({top:e.getBoundingClientRect().top+scrollY-85,behavior:'instant'})});await p.waitForTimeout(400);console.log(l,await p.locator('.table-wrap').evaluate(e=>({left:e.scrollLeft,top:e.getBoundingClientRect().top})));await p.screenshot({path:'specs/reviews/843-evidence/843-review-1-7f018940/'+l+'-320-table-right-settled.png'});}await b.close();})();
JS"
